// msg.payload — весь текст лога одной строкой
const T = 2; // период опроса, с (Вариант №30)

// Допустимые диапазоны для датчиков: s1 (MQ-2): 0-100%, s2 (LDR): 0-100%, s3 (SW): 0 или 1
const RANGES = { 
    s1:, 
    s2:, 
    s3: [0, 1] 
};

const text = String(msg.payload).replace(/^\uFEFF/, ''); 
const sql = [];

// Разбиваем лог на отдельные строки
text.split(\(/\r\)?\n/).forEach(raw => { 
    const line = raw.trim();
    if (!line) return;

    // Строка вида: DATA n=3 s1=25.4 s2=60.0 s3=0
    const parts = line.split(' ');
    const kind = parts[0]; // DATA или EVENT 
    const f = {};

    // Собираем пары ключ=значение
    parts.slice(1).forEach(p => { 
        const kv = p.split('='); 
        if (kv[0] && kv[1]) {
            f[kv[0]] = kv[1];
        }
    });

    const n = parseInt(f.n); 
    if (isNaN(n)) return; 
    const t = n * T; // Вычисляем время t_s = n * T

    if (kind === 'DATA') {
        ['s1', 's2', 's3'].forEach(s => { 
            const v = parseFloat(f[s]);
            if (!isNaN(v)) {
                sql.push(`INSERT INTO readings(n,t_s,sensor,value) VALUES(${n},${t},'${s}',${v});`);
            }
            // Проверка выхода за границы диапазона (для генерации FAULT)
            if (isNaN(v) || v < RANGES[s][0] || v > RANGES[s][1]) {
                sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'FAULT','датчик ${s} вне диапазона');`);
            }
        });
    } else if (kind === 'EVENT') {
        sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'${f.type}','');`);
    }
});

// Формируем заголовок очистки таблиц, чтобы данные при перезапуске не дублировались
const head = 'BEGIN;\nDELETE FROM readings;\nDELETE FROM events;\n' + "DELETE FROM sqlite_sequence WHERE name IN ('readings','events');\n";
const toFile = { payload: head + sql.join('\n') + '\nCOMMIT;\n' }; 

// Отдаем результат на второй выход (для записи в файл/БД)
return [null, toFile];
